-- A first draft of `descriptionFa` for every brand the storefront shows, for a
-- person to review and rewrite in the admin panel.
--
-- The brand page (`/brands/<slug>`) opens with this text and uses it as the
-- page's meta description, so a brand with none falls back to a generic
-- sentence. Each draft says only what the brand is and what a card for it is
-- generally used for. It names no price, region, denomination or delivery time:
-- those belong to the products, and the storefront already shows them live.
--
-- Data only, and it never overwrites an edit: a brand that already has a
-- description (written in the panel) is left exactly as it is. Re-running the
-- migration changes nothing.

UPDATE "Brand" AS b
SET "descriptionFa" = v.description,
    "updatedAt" = now()
FROM (VALUES
  ('airbnb', $md$ایربی‌ان‌بی (Airbnb) بستری برای رزرو اقامتگاه و تجربه‌های سفر در شهرهای مختلف دنیا است. گیفت‌کارت آن اعتباری است که هنگام رزرو اقامت یا تجربه خرج می‌شود.$md$),
  ('amazon', $md$آمازون (Amazon) یکی از بزرگ‌ترین فروشگاه‌های اینترنتی دنیا است. گیفت‌کارت آمازون اعتباری برای خرید از فروشگاه آمازون همان منطقه‌ای است که کارت برای آن صادر شده است.$md$),
  ('apple', $md$گیفت‌کارت اپل (Apple) اعتباری است که در حساب اپل‌آی‌دی شارژ می‌شود و برای خرید از اپ‌استور، اشتراک‌هایی مثل Apple Music و iCloud و دیگر خدمات اپل خرج می‌شود. منطقه‌ی کارت باید با منطقه‌ی حساب شما یکی باشد.$md$),
  ('blizzard', $md$بلیزارد (Blizzard) سازنده‌ی بازی‌هایی مانند World of Warcraft، Overwatch و Diablo است. گیفت‌کارت آن اعتباری برای خرید بازی و محتوای درون‌بازی در پلتفرم Battle.net است.$md$),
  ('fortnite', $md$فورتنایت (Fortnite) بازی آنلاین شرکت Epic Games است. این کارت‌ها برای خرید محتوای درون‌بازی مانند V-Bucks و آیتم‌های ظاهری استفاده می‌شوند.$md$),
  ('free-fire', $md$فری فایر (Free Fire) یک بازی بتل‌رویال موبایلی از شرکت Garena است. این کارت‌ها برای شارژ الماس و خرید آیتم‌های درون‌بازی به کار می‌روند.$md$),
  ('google-play', $md$گیفت‌کارت گوگل پلی (Google Play) اعتباری است که در حساب گوگل شارژ می‌شود و برای خرید برنامه، بازی، اشتراک و محتوای درون‌برنامه‌ای در فروشگاه گوگل پلی خرج می‌شود. منطقه‌ی کارت باید با منطقه‌ی حساب شما یکی باشد.$md$),
  ('hotels-com', $md$هتلز دات کام (Hotels.com) سایت رزرو هتل و اقامتگاه در شهرهای مختلف دنیا است. گیفت‌کارت آن اعتباری است که هنگام رزرو اقامت خرج می‌شود.$md$),
  ('jawaker', $md$جواکر (Jawaker) یک برنامه‌ی بازی‌های ورق و تخته‌ای آنلاین است که در کشورهای عربی‌زبان محبوب است. این کارت‌ها برای شارژ اعتبار و خرید امکانات درون‌برنامه استفاده می‌شوند.$md$),
  ('netflix', $md$نتفلیکس (Netflix) سرویس پخش آنلاین فیلم و سریال است. گیفت‌کارت آن اعتباری است که برای پرداخت هزینه‌ی اشتراک در حساب نتفلیکس شارژ می‌شود.$md$),
  ('nike', $md$نایکی (Nike) برند پوشاک، کفش و تجهیزات ورزشی است. گیفت‌کارت آن اعتباری برای خرید از فروشگاه‌های نایکی است.$md$),
  ('nintendo', $md$نینتندو (Nintendo) سازنده‌ی کنسول سوییچ و بازی‌هایی مانند Mario و Zelda است. گیفت‌کارت آن اعتباری است که برای خرید بازی و محتوای اضافه از فروشگاه دیجیتال نینتندو (eShop) خرج می‌شود. منطقه‌ی کارت باید با منطقه‌ی حساب شما یکی باشد.$md$),
  ('playstation', $md$گیفت‌کارت پلی‌استیشن (PlayStation) اعتباری است که در حساب PlayStation Network شارژ می‌شود و برای خرید بازی، محتوای اضافه و اشتراک از PlayStation Store خرج می‌شود. منطقه‌ی کارت باید با منطقه‌ی حساب شما یکی باشد.$md$),
  ('pubg', $md$پابجی (PUBG) از پرطرفدارترین بازی‌های بتل‌رویال است. این کارت‌ها برای شارژ UC و خرید آیتم‌های درون‌بازی استفاده می‌شوند.$md$),
  ('razer-gold', $md$ریزر گلد (Razer Gold) اعتبار دیجیتالی شرکت Razer است که در بسیاری از بازی‌ها و خدمات دیجیتال قابل استفاده است.$md$),
  ('roblox', $md$روبلاکس (Roblox) بستری برای ساخت و بازی کردن هزاران بازی آنلاین است. گیفت‌کارت آن برای خرید Robux و آیتم‌های درون‌بازی استفاده می‌شود.$md$),
  ('shein', $md$شیین (SHEIN) فروشگاه اینترنتی پوشاک و لوازم جانبی است. گیفت‌کارت آن اعتباری برای خرید از فروشگاه شیین است.$md$),
  ('spotify', $md$اسپاتیفای (Spotify) سرویس پخش آنلاین موسیقی و پادکست است. گیفت‌کارت آن اعتباری است که برای پرداخت هزینه‌ی اشتراک پریمیوم در حساب اسپاتیفای شارژ می‌شود.$md$),
  ('steam', $md$استیم (Steam) بزرگ‌ترین فروشگاه و پلتفرم بازی‌های رایانه‌ای است. گیفت‌کارت استیم اعتباری است که در کیف پول حساب استیم شارژ می‌شود و برای خرید بازی و محتوای اضافه خرج می‌شود.$md$),
  ('tinder', $md$تیندر (Tinder) یک برنامه‌ی آشنایی و دوست‌یابی است. گیفت‌کارت آن برای خرید اشتراک و امکانات ویژه‌ی درون‌برنامه استفاده می‌شود.$md$),
  ('twitch', $md$توییچ (Twitch) پلتفرم پخش زنده‌ی بازی و محتوای سرگرمی است. گیفت‌کارت آن برای خرید اشتراک کانال‌ها و حمایت از استریمرها استفاده می‌شود.$md$),
  ('uber', $md$اوبر (Uber) سرویس درخواست خودرو و سفر درون‌شهری و سفارش غذا است. گیفت‌کارت آن اعتباری است که برای پرداخت هزینه‌ی سفر و سفارش خرج می‌شود.$md$),
  ('xbox', $md$گیفت‌کارت ایکس‌باکس (Xbox) اعتباری است که در حساب مایکروسافت شارژ می‌شود و برای خرید بازی، محتوای اضافه و اشتراک‌هایی مانند Game Pass از فروشگاه ایکس‌باکس خرج می‌شود. منطقه‌ی کارت باید با منطقه‌ی حساب شما یکی باشد.$md$),
  ('zara', $md$زارا (Zara) برند پوشاک و مد است. گیفت‌کارت آن اعتباری برای خرید از فروشگاه‌های زارا است.$md$)
) AS v(slug, description)
WHERE b."slug" = v.slug
  AND (b."descriptionFa" IS NULL OR btrim(b."descriptionFa") = '');
